            int p=positions[2].get(o);
            int moveCost = Math.max(freq[p][0]-v,0)+Math.max(freq[p][1]-k,0)+Math.max(freq[p][2]-o,0)-1;
            res = Math.min(res, solve(v,k,o+1,2,totalV,totalK,totalO,positions,freq,dp)+moveCost);
