#include <bits/stdc++.h>
using namespace std;

int solve(int v, int k, int o, int last, int totalV, int totalK, int totalO,
          vector<vector<int>> &positions, vector<vector<int>> &freq,
          vector<vector<vector<vector<int>>>> &dp) {
    if (v == totalV && k == totalK && o == totalO) return 0;
    if (dp[v][k][o][last] != -1) return dp[v][k][o][last];
    int res = INT_MAX / 2;

    if (v < totalV) {
        int p = positions[0][v];
        int moveCost = max(freq[p][0] - v, 0) + max(freq[p][1] - k, 0) + max(freq[p][2] - o, 0) - 1;
        res = min(res, solve(v + 1, k, o, 0, totalV, totalK, totalO, positions, freq, dp) + moveCost);
    }

    if (k < totalK && last != 0) {
        int p = positions[1][k];
        int moveCost = max(freq[p][0] - v, 0) + max(freq[p][1] - k, 0) + max(freq[p][2] - o, 0) - 1;
        res = min(res, solve(v, k + 1, o, 1, totalV, totalK, totalO, positions, freq, dp) + moveCost);
    }

    if (o < totalO) {
        int p = positions[2][o];
        int moveCost = max(freq[p][0] - v, 0) + max(freq[p][1] - k, 0) + max(freq[p][2] - o, 0) - 1;
        res = min(res, solve(v, k, o + 1, 2, totalV, totalK, totalO, positions, freq, dp) + moveCost);
    }

    return dp[v][k][o][last] = res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string line;
    getline(cin, line); // consume leftover newline
    getline(cin, line);
    vector<char> c(line.begin(), line.end());

    int totalV = 0, totalK = 0, totalOther = 0;
    vector<vector<int>> positions(3);
    vector<vector<int>> frequency(n + 1, vector<int>(3, 0));

    int idx = 0;
    for (char ch : c) {
        if (ch == 'V') {
            frequency[idx + 1] = frequency[idx];
            frequency[idx + 1][0]++;
            totalV++;
            positions[0].push_back(idx + 1);
        } else if (ch == 'K') {
            frequency[idx + 1] = frequency[idx];
            frequency[idx + 1][1]++;
            totalK++;
            positions[1].push_back(idx + 1);
        } else {
            frequency[idx + 1] = frequency[idx];
            frequency[idx + 1][2]++;
            totalOther++;
            positions[2].push_back(idx + 1);
        }
        idx++;
    }

    vector<vector<vector<vector<int>>>> dp(totalV + 1,
        vector<vector<vector<int>>>(totalK + 1,
            vector<vector<int>>(totalOther + 1,
                vector<int>(3, -1))));

    cout << solve(0, 0, 0, 2, totalV, totalK, totalOther, positions, frequency, dp) << "\n";

    return 0;
}

